/**
 * Sandbox counterparty scores (weighted/shrink formula + customs enrichment).
 * Regenerated by: python3 scripts/aggregate-customs-companies.py &&
 *   npx tsx scripts/recalculate-counterparty-scores.ts
 */
import type { PlatformCounterpartyScore } from "../types/platform";
import raw from "./counterparty-sandbox-scores.json";

export interface SandboxScoresFile {
  formula: string;
  generatedAt: string;
  customsGeneratedAt: string;
  customsSources: string[];
  counterparties: PlatformCounterpartyScore[];
}

export const counterpartySandboxMeta: Omit<SandboxScoresFile, "counterparties"> = {
  formula: raw.formula,
  generatedAt: raw.generatedAt,
  customsGeneratedAt: raw.customsGeneratedAt,
  customsSources: raw.customsSources,
};

/** Platform counterparties rescored with the 2026-07-30 sandbox formula. */
export const sandboxCounterparties: PlatformCounterpartyScore[] =
  raw.counterparties as PlatformCounterpartyScore[];
